// pure JS, no AI calls here
// reads the original message plus both Groq responses for "this" item (paired by item index)
// and applies fixed if/else rules to pick a destination queue and an escalation flag

const original = $('Ingested Message').item.json;
const classifyResponse = $('Classify Message').item.json;
const enrichResponse = $('Enrich Message').item.json;

// Groq responses put the model's JSON reply as a string at
// choices[0].message.content, so we have to parse that string
function parseLLMJson(response) {
  const content = response.choices[0].message.content;
  return JSON.parse(content);
}

const classification = parseLLMJson(classifyResponse);
const enrichment = parseLLMJson(enrichResponse);

const category = classification.category;
const priority = classification.priority;
const confidence_score = classification.confidence_score;

// Rule 1: deterministic category -> team mapping
let destination_queue;
if (category === 'Bug Report') {
  destination_queue = 'Engineering'; 
} else if (category === 'Incident/Outage') {
  destination_queue = 'Engineering'; 
} else if (category === 'Billing Issue') {
  destination_queue = 'Billing';
} else if (category === 'Feature Request') {
  destination_queue = 'Product';
} else if (category === 'Technical Question') {
  destination_queue = 'IT/Security';
} else {
  destination_queue = 'Escalation'; 
}

// Rule 2: escalation flag: any ONE of these four conditions overrides the routing above 
const messageText = (original.message || '').toLowerCase();

// literal escalation keywords in the raw customer text
const escalationKeywords = ['outage', 'down for all users'];
const hasEscalationKeyword = escalationKeywords.some(k => messageText.includes(k));

// classifier itself was not confident
const lowConfidence = confidence_score < 70;

// billing issue where a dollar amount mentioned in the text exceeds $500
let billingOverThreshold = false;
if (category === 'Billing Issue') {
  const amounts = messageText.match(/\$[\d,]+(\.\d+)?/g) || [];
  billingOverThreshold = amounts.some(a => parseFloat(a.replace(/[$,]/g, '')) > 500);
}

// security/compliance keywords (ArcVault's customers are explicitly compliance-heavy)
// the whole product is audit logs, so a security incident is a distinct risk category
// from a generic urgent-sounding message and deserves its own check
const securityKeywords = ['breach', 'unauthorized access', 'data leak'];
const hasSecurityKeyword = securityKeywords.some(k => messageText.includes(k));

const escalation_flag = lowConfidence || hasEscalationKeyword || billingOverThreshold || hasSecurityKeyword;

// escalation always wins over the normal routing rule above
if (escalation_flag) {
  destination_queue = 'Escalation';
}

return {
  json: {
    id: original.id,
    source: original.source,
    message: original.message,
    category,
    priority,
    confidence_score,
    core_issue: enrichment.core_issue,
    extracted_identifiers: enrichment.extracted_identifiers,
    urgency_signal: enrichment.urgency_signal,
    destination_queue,
    escalation_flag
  }
};
